<section class="page-head"><div><span class="eyebrow"><?=e(__('ui.connect'))?></span><h1><?=e(__('messaging.title'))?></h1></div></section><div class="messages-layout"><aside class="conversation-list"><?php if(!$conversations):?><div class="empty-mini"><?=e(__('messaging.empty'))?></div><?php else: foreach($conversations as $c):?><a class="conversation" href="<?=e(url('/messages/'.$c['id']))?>"><strong><?=e($c['subject'] ?: ('#'.$c['id']))?></strong><small><?=e(mb_strimwidth((string)($c['last_body']??''),0,60,'…'))?></small></a><?php endforeach;endif;?></aside><section class="message-panel"><?php if(!$conversationId):?><div class="empty-state compact"><h2><?=e(__('messaging.title'))?></h2><p><?=e(__('messaging.empty'))?></p></div><?php else: foreach($messages as $m):?><div class="message <?=((int)$m['sender_user_id']===(int)\App\Core\Auth::id())?'mine':''?>"><p><?=e($m['body'])?></p><small><?=e($m['email'])?> · <?=e($m['created_at'])?></small></div><?php endforeach;?><form method="post" action="<?=e(url('/messages/'.$conversationId))?>" class="message-compose"><?=csrf_field()?><textarea name="body" required rows="3" placeholder="<?=e(__('messaging.body'))?>"></textarea><button class="btn primary" type="submit"><?=e(__('messaging.send'))?></button></form><?php endif;?></section></div>
